-- Idempotent seed for the 38 published blog articles shown in the student blog.
-- Run with: mysql online_learning_system < database/seeds/demo_blog_showcase.sql
-- All records are attributed to the existing manager account so manager and student views share the same posts.
SET NAMES utf8mb4;
START TRANSACTION;
SET @blog_manager_id := (SELECT id FROM users WHERE email='manager@onlinelearning.local' LIMIT 1);

INSERT INTO posts (author_id,title,slug,summary,content,category,thumbnail_url,featured,published,deleted,status,created_at,updated_at,published_at)
SELECT @blog_manager_id, seed.title, seed.slug, seed.summary, seed.content, seed.category, seed.thumbnail_url, seed.featured, b'1', b'0', 'PUBLISHED', seed.created_at, seed.created_at, seed.created_at
FROM (
  SELECT 1 AS seed_no, '5 Kỹ Năng Cốt Lõi Giúp Chinh Phục Kỳ Thực Tập IT Đầu Tiên' AS title, 'demo-blog-1' AS slug, 'Làm thế nào để ngay từ năm 3, bạn đã có thể bắt nhịp nhanh với môi trường thực tế? Cùng phân tích các yêu cầu về Git, Clean Code và tư duy làm việc nhóm.' AS summary, '<p>Kỳ thực tập đầu tiên không chỉ là cột mốc tốt nghiệp mà còn là phép thử quyết định tốc độ thăng tiến của một lập trình viên. Tuy nhiên, phần lớn sinh viên thường rơi vào cái bẫy “chỉ chăm chăm học ngôn ngữ” mà bỏ quên các tiêu chuẩn vận hành trong dự án thực tế.</p>
      <h3>1. Làm chủ Git &amp; Quy trình tạo Pull Request (PR) chuẩn chỉ</h3><p>Trong doanh nghiệp, không ai làm việc một mình trên nhánh <code>main</code>. Bạn cần biết cách rebase, giải quyết conflict và mô tả thay đổi để người khác review nhanh chóng.</p>
      <blockquote>“Nhà tuyển dụng không tìm kiếm một người thuộc lòng mọi cú pháp; họ tìm kiếm một đồng đội có khả năng đọc hiểu code người khác.”</blockquote>
      <h3>2. Tư duy Clean Code &amp; Kiểm thử tự động (Unit Test)</h3><p>Viết mã chạy được mới chỉ là bước khởi đầu. Một lập trình viên tốt còn đặt tên biến chuẩn ý nghĩa, chia nhỏ hàm và viết kiểm thử để phát hiện lỗi trước khi thay đổi được tích hợp.</p>
      <h3>3. Giao tiếp và cập nhật tiến độ</h3><p>Hãy chủ động báo sớm khi gặp vướng mắc, mô tả điều đã thử và chia sẻ kết quả. Giao tiếp rõ ràng giúp nhóm hỗ trợ đúng lúc và giúp bạn học nhanh hơn.</p>
      <h3>4. Đọc tài liệu và đặt câu hỏi đúng</h3><p>Biết tìm trong tài liệu chính thức, issue và codebase là kỹ năng quan trọng. Trước khi hỏi, hãy chuẩn bị bối cảnh, kết quả mong đợi và lỗi đang gặp.</p>
      <h3>5. Quản lý thời gian, giữ lời hứa</h3><p>Ước lượng vừa sức, chia việc thành bước nhỏ và cập nhật khi kế hoạch thay đổi. Sự tin cậy trong công việc thường bắt đầu từ những cam kết đơn giản.</p>' AS content, 'Lộ trình nghề nghiệp' AS category, 'https://images.unsplash.com/photo-1461749280684-dccba630e2f6?auto=format&fit=crop&w=1200&q=80' AS thumbnail_url, 1 AS featured, '2026-09-18 09:00:00' AS created_at
  UNION ALL
  SELECT 2 AS seed_no, 'Ứng Dụng Active Recall Khi Tự Học Lập Trình & Khung MVC' AS title, 'demo-blog-2' AS slug, 'Thay vì đọc lại tài liệu thụ động, hãy chủ động truy hồi kiến thức và thực hành quiz ngắn để ghi nhớ sâu các luồng Controller - Service - Repository.' AS summary, '<p>Đọc lại ghi chú nhiều lần tạo cảm giác quen thuộc, nhưng chưa chắc giúp bạn tự giải thích hoặc áp dụng kiến thức. Active Recall thay đổi cách học bằng việc chủ động nhớ lại trước khi xem đáp án.</p><h3>Chia luồng MVC thành câu hỏi</h3><p>Với mỗi chức năng, hãy tự hỏi request đi qua Controller, Service và Repository như thế nào. Viết câu trả lời bằng lời của mình, sau đó mở code để đối chiếu.</p><h3>Luyện tập ngắn và có khoảng nghỉ</h3><p>Tạo quiz nhỏ sau buổi học, ôn lại sau một ngày rồi tăng dần khoảng cách. Khi sai, ghi lại nguyên nhân và thử giải thích lại mà không nhìn tài liệu.</p><blockquote>Học tốt là có thể gọi lại và sử dụng kiến thức khi cần, không chỉ nhận ra nó trên trang sách.</blockquote><p>Kết hợp Active Recall với một bài tập nhỏ sẽ giúp bạn phát hiện phần còn hổng và nhớ lâu hơn.</p>' AS content, 'Phương pháp học tập' AS category, 'https://images.unsplash.com/photo-1515879218367-8466d910aaa4?auto=format&fit=crop&w=1200&q=80' AS thumbnail_url, 1 AS featured, '2026-09-12 09:00:00' AS created_at
  UNION ALL
  SELECT 3 AS seed_no, 'Cân Bằng Giữa Thẩm Mỹ Hiện Đại Và Tính Tiện Dụng Trong UI' AS title, 'demo-blog-3' AS slug, 'Khám phá các nguyên tắc thiết kế gần với thị giác, phân cấp thông tin và khả năng sử dụng để tạo trải nghiệm học trực tuyến dễ hiểu, nhất quán.' AS summary, '<p>Một giao diện đẹp cần giúp người dùng hoàn thành công việc dễ dàng. Màu sắc và hiệu ứng chỉ có ý nghĩa khi chúng hỗ trợ phân cấp thông tin và chỉ dẫn thao tác.</p><h3>Bắt đầu từ nhu cầu</h3><p>Xác định người dùng đang cần tìm khóa học, theo dõi tiến độ hay tiếp tục bài học. Đưa hành động chính lên vị trí dễ thấy và giảm những lựa chọn không cần thiết.</p><h3>Duy trì tính nhất quán</h3><p>Dùng chung quy tắc cho khoảng cách, kiểu chữ, màu trạng thái và nút bấm. Các thành phần quen thuộc giúp người học chuyển giữa các trang mà không phải đoán lại.</p><h3>Kiểm tra trên thiết bị thật</h3><p>Thử các luồng quan trọng ở kích thước màn hình khác nhau, kiểm tra độ tương phản và hỏi người dùng xem họ có tìm thấy thông tin cần thiết không.</p>' AS content, 'Thiết kế UI/UX' AS category, 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=80' AS thumbnail_url, 1 AS featured, '2026-09-05 09:00:00' AS created_at
  UNION ALL
  SELECT 4 AS seed_no, 'Tối Ưu Query Database Cho Ứng Dụng Học Tập' AS title, 'demo-blog-4' AS slug, 'Một số cách đọc execution plan, chọn index phù hợp và phân trang dữ liệu để API phản hồi ổn định khi số lượng khóa học tăng lên.' AS summary, '<p>Khi dữ liệu tăng, một truy vấn chạy nhanh trên máy cá nhân có thể trở thành nút thắt của API. Hãy đo trước khi tối ưu để biết thời gian nằm ở truy vấn nào và dữ liệu nào đang được đọc.</p><h3>Đọc execution plan</h3><p>Kiểm tra cách cơ sở dữ liệu tìm bản ghi, số dòng ước tính và các bước join. So sánh kế hoạch trước và sau thay đổi thay vì chỉ dựa vào cảm giác.</p><h3>Chọn index theo truy vấn</h3><p>Index phù hợp với điều kiện lọc và sắp xếp thường giúp giảm lượng dữ liệu cần quét. Index cũng làm tăng chi phí ghi, nên cần cân nhắc các truy vấn thực tế.</p><h3>Phân trang có giới hạn</h3><p>Trả về đúng số dòng cần dùng, đặt giới hạn kích thước trang và chọn thứ tự ổn định. Sau đó theo dõi độ trễ để xác nhận hiệu quả.</p>' AS content, 'Lập trình & Công nghệ' AS category, 'https://images.unsplash.com/photo-1498050108023-c5249f4df085?auto=format&fit=crop&w=1200&q=80' AS thumbnail_url, 1 AS featured, '2026-08-28 09:00:00' AS created_at
  UNION ALL
  SELECT 5 AS seed_no, 'Java Collections và Stream API qua ví dụ thực tế' AS title, 'demo-blog-5' AS slug, 'Chọn cấu trúc dữ liệu phù hợp, kết hợp Stream để xử lý tập hợp rõ ràng và dễ bảo trì.' AS summary, '<p>Chọn cấu trúc dữ liệu phù hợp, kết hợp Stream để xử lý tập hợp rõ ràng và dễ bảo trì.</p><h3>Bắt đầu từ mục tiêu cụ thể</h3><p>Trước khi áp dụng “Java Collections và Stream API qua ví dụ thực tế”, hãy xác định vấn đề cần giải quyết và kết quả mong muốn. Ghi lại bối cảnh hiện tại để có thể so sánh sau khi thử cách làm mới.</p><h3>Thực hiện theo từng bước</h3><p>Chia dự án thành những bước nhỏ, kiểm tra kết quả ở mỗi giai đoạn và ghi lại điều gì hiệu quả. Nếu gặp trở ngại, hãy thay đổi một yếu tố mỗi lần để hiểu nguyên nhân.</p><blockquote>Ưu tiên cách làm đơn giản, có thể kiểm tra và cải thiện dựa trên phản hồi thực tế.</blockquote><h3>Đánh giá và tiếp tục cải thiện</h3><p>Cuối cùng, xem lại mục tiêu ban đầu, hỏi ý kiến người liên quan và điều chỉnh quy trình. Một thói quen đều đặn thường hữu ích hơn một lần cố gắng quá sức.</p>' AS content, 'Lập trình & Công nghệ' AS category, 'https://images.unsplash.com/photo-1633356122544-f134324a6cee?auto=format&fit=crop&w=1200&q=80' AS thumbnail_url, 0 AS featured, '2026-08-27 09:00:00' AS created_at
  UNION ALL
  SELECT 6 AS seed_no, 'Thiết kế REST API nhất quán cho ứng dụng học tập' AS title, 'demo-blog-6' AS slug, 'Thống nhất tài nguyên, mã trạng thái và quy tắc phân trang để API dễ tích hợp.' AS summary, '<p>Thống nhất tài nguyên, mã trạng thái và quy tắc phân trang để API dễ tích hợp.</p><h3>Bắt đầu từ mục tiêu cụ thể</h3><p>Trước khi áp dụng “Thiết kế REST API nhất quán cho ứng dụng học tập”, hãy xác định vấn đề cần giải quyết và kết quả mong muốn. Ghi lại bối cảnh hiện tại để có thể so sánh sau khi thử cách làm mới.</p><h3>Thực hiện theo từng bước</h3><p>Chia dự án thành những bước nhỏ, kiểm tra kết quả ở mỗi giai đoạn và ghi lại điều gì hiệu quả. Nếu gặp trở ngại, hãy thay đổi một yếu tố mỗi lần để hiểu nguyên nhân.</p><blockquote>Ưu tiên cách làm đơn giản, có thể kiểm tra và cải thiện dựa trên phản hồi thực tế.</blockquote><h3>Đánh giá và tiếp tục cải thiện</h3><p>Cuối cùng, xem lại mục tiêu ban đầu, hỏi ý kiến người liên quan và điều chỉnh quy trình. Một thói quen đều đặn thường hữu ích hơn một lần cố gắng quá sức.</p>' AS content, 'Lập trình & Công nghệ' AS category, 'https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=1200&q=80' AS thumbnail_url, 0 AS featured, '2026-08-26 09:00:00' AS created_at
  UNION ALL
  SELECT 7 AS seed_no, 'Quản lý transaction trong Spring Boot' AS title, 'demo-blog-7' AS slug, 'Xác định ranh giới transaction và xử lý lỗi để dữ liệu không rơi vào trạng thái dở dang.' AS summary, '<p>Xác định ranh giới transaction và xử lý lỗi để dữ liệu không rơi vào trạng thái dở dang.</p><h3>Bắt đầu từ mục tiêu cụ thể</h3><p>Trước khi áp dụng “Quản lý transaction trong Spring Boot”, hãy xác định vấn đề cần giải quyết và kết quả mong muốn. Ghi lại bối cảnh hiện tại để có thể so sánh sau khi thử cách làm mới.</p><h3>Thực hiện theo từng bước</h3><p>Chia dự án thành những bước nhỏ, kiểm tra kết quả ở mỗi giai đoạn và ghi lại điều gì hiệu quả. Nếu gặp trở ngại, hãy thay đổi một yếu tố mỗi lần để hiểu nguyên nhân.</p><blockquote>Ưu tiên cách làm đơn giản, có thể kiểm tra và cải thiện dựa trên phản hồi thực tế.</blockquote><h3>Đánh giá và tiếp tục cải thiện</h3><p>Cuối cùng, xem lại mục tiêu ban đầu, hỏi ý kiến người liên quan và điều chỉnh quy trình. Một thói quen đều đặn thường hữu ích hơn một lần cố gắng quá sức.</p>' AS content, 'Lập trình & Công nghệ' AS category, 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1200&q=80' AS thumbnail_url, 0 AS featured, '2026-08-25 09:00:00' AS created_at
  UNION ALL
  SELECT 8 AS seed_no, 'Chọn index SQL dựa trên truy vấn thực tế' AS title, 'demo-blog-8' AS slug, 'Đọc kế hoạch thực thi và đo truy vấn trước khi quyết định thêm index.' AS summary, '<p>Đọc kế hoạch thực thi và đo truy vấn trước khi quyết định thêm index.</p><h3>Bắt đầu từ mục tiêu cụ thể</h3><p>Trước khi áp dụng “Chọn index SQL dựa trên truy vấn thực tế”, hãy xác định vấn đề cần giải quyết và kết quả mong muốn. Ghi lại bối cảnh hiện tại để có thể so sánh sau khi thử cách làm mới.</p><h3>Thực hiện theo từng bước</h3><p>Chia dự án thành những bước nhỏ, kiểm tra kết quả ở mỗi giai đoạn và ghi lại điều gì hiệu quả. Nếu gặp trở ngại, hãy thay đổi một yếu tố mỗi lần để hiểu nguyên nhân.</p><blockquote>Ưu tiên cách làm đơn giản, có thể kiểm tra và cải thiện dựa trên phản hồi thực tế.</blockquote><h3>Đánh giá và tiếp tục cải thiện</h3><p>Cuối cùng, xem lại mục tiêu ban đầu, hỏi ý kiến người liên quan và điều chỉnh quy trình. Một thói quen đều đặn thường hữu ích hơn một lần cố gắng quá sức.</p>' AS content, 'Lập trình & Công nghệ' AS category, 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=80' AS thumbnail_url, 0 AS featured, '2026-08-24 09:00:00' AS created_at
  UNION ALL
  SELECT 9 AS seed_no, 'Dùng Redis cache cho dữ liệu đọc nhiều' AS title, 'demo-blog-9' AS slug, 'Chọn dữ liệu phù hợp để cache, đặt thời hạn và làm mới khi nội dung thay đổi.' AS summary, '<p>Chọn dữ liệu phù hợp để cache, đặt thời hạn và làm mới khi nội dung thay đổi.</p><h3>Bắt đầu từ mục tiêu cụ thể</h3><p>Trước khi áp dụng “Dùng Redis cache cho dữ liệu đọc nhiều”, hãy xác định vấn đề cần giải quyết và kết quả mong muốn. Ghi lại bối cảnh hiện tại để có thể so sánh sau khi thử cách làm mới.</p><h3>Thực hiện theo từng bước</h3><p>Chia dự án thành những bước nhỏ, kiểm tra kết quả ở mỗi giai đoạn và ghi lại điều gì hiệu quả. Nếu gặp trở ngại, hãy thay đổi một yếu tố mỗi lần để hiểu nguyên nhân.</p><blockquote>Ưu tiên cách làm đơn giản, có thể kiểm tra và cải thiện dựa trên phản hồi thực tế.</blockquote><h3>Đánh giá và tiếp tục cải thiện</h3><p>Cuối cùng, xem lại mục tiêu ban đầu, hỏi ý kiến người liên quan và điều chỉnh quy trình. Một thói quen đều đặn thường hữu ích hơn một lần cố gắng quá sức.</p>' AS content, 'Lập trình & Công nghệ' AS category, 'https://images.unsplash.com/photo-1563013544-824ae1b704d3?auto=format&fit=crop&w=1200&q=80' AS thumbnail_url, 0 AS featured, '2026-08-23 09:00:00' AS created_at
  UNION ALL
  SELECT 10 AS seed_no, 'Quản lý state React cho màn hình nhiều bộ lọc' AS title, 'demo-blog-10' AS slug, 'Giữ bộ lọc, từ khóa và phân trang đồng bộ để giao diện dễ dự đoán.' AS summary, '<p>Giữ bộ lọc, từ khóa và phân trang đồng bộ để giao diện dễ dự đoán.</p><h3>Bắt đầu từ mục tiêu cụ thể</h3><p>Trước khi áp dụng “Quản lý state React cho màn hình nhiều bộ lọc”, hãy xác định vấn đề cần giải quyết và kết quả mong muốn. Ghi lại bối cảnh hiện tại để có thể so sánh sau khi thử cách làm mới.</p><h3>Thực hiện theo từng bước</h3><p>Chia dự án thành những bước nhỏ, kiểm tra kết quả ở mỗi giai đoạn và ghi lại điều gì hiệu quả. Nếu gặp trở ngại, hãy thay đổi một yếu tố mỗi lần để hiểu nguyên nhân.</p><blockquote>Ưu tiên cách làm đơn giản, có thể kiểm tra và cải thiện dựa trên phản hồi thực tế.</blockquote><h3>Đánh giá và tiếp tục cải thiện</h3><p>Cuối cùng, xem lại mục tiêu ban đầu, hỏi ý kiến người liên quan và điều chỉnh quy trình. Một thói quen đều đặn thường hữu ích hơn một lần cố gắng quá sức.</p>' AS content, 'Lập trình & Công nghệ' AS category, 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?auto=format&fit=crop&w=1200&q=80' AS thumbnail_url, 0 AS featured, '2026-08-22 09:00:00' AS created_at
  UNION ALL
