WHERE @blog_manager_id IS NOT NULL
ON DUPLICATE KEY UPDATE
  author_id=VALUES(author_id), title=VALUES(title), summary=VALUES(summary), content=VALUES(content),
  category=VALUES(category), thumbnail_url=VALUES(thumbnail_url), featured=VALUES(featured),
  published=VALUES(published), deleted=VALUES(deleted), status=VALUES(status),
  created_at=VALUES(created_at), updated_at=VALUES(updated_at), published_at=VALUES(published_at), deleted_at=NULL;

COMMIT;
SELECT COUNT(*) AS published_showcase_posts FROM posts WHERE slug LIKE 'demo-blog-%' AND published=b'1' AND deleted=b'0';
